arguments.new_str:
using Microsoft.Extensions.ML;
using ChurnPredictor.Models;
using ChurnPredictor.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<ChurnModelService>();
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelName: "ChurnModel", filePath: null!, watchForChanges: false);

var app = builder.Build();

// Train model on startup and configure the prediction engine pool
var churnService = app.Services.GetRequiredService<ChurnModelService>();
churnService.TrainModel();

// Re-register the pool now that we know the model path
var poolOptions = app.Services.GetRequiredService<Microsoft.Extensions.Options.IOptions<
    Microsoft.Extensions.ML.PredictionEnginePoolOptions<CustomerData, ChurnPrediction>>>();

// Reconfigure with actual model path using a file-based loader
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelName: "ChurnModel", filePath: churnService.ModelPath, watchForChanges: false);

// Since we can't easily reconfigure after build, use a direct approach
var mlContext = new Microsoft.ML.MLContext(seed: 42);
Microsoft.ML.ITransformer trainedModel;
Microsoft.ML.DataViewSchema modelSchema;
using (var stream = File.OpenRead(churnService.ModelPath))
{
    trainedModel = mlContext.Model.Load(stream, out modelSchema);
}

app.MapGet("/", () => "Hello");

app.MapPost("/api/predict", (CustomerData customer) =>
{
    var predEngine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(trainedModel);
    var prediction = predEngine.Predict(customer);
    return Results.Ok(new
    {
        prediction.PredictedLabel,
        prediction.Probability,
        prediction.Score,
        WillChurn = prediction.PredictedLabel ? "Yes" : "No"
    });
});

app.MapGet("/api/model/metrics", () =>
{
    var metrics = churnService.Metrics;
    if (metrics is null)
        return Results.NotFound("Model has not been trained yet.");

    return Results.Ok(metrics);
});

app.Run();

