using Microsoft.Extensions.ML;
using ChurnPredictor.Models;
using ChurnPredictor.Services;

var builder = WebApplication.CreateBuilder(args);

// Register the churn model service and train the model eagerly
builder.Services.AddSingleton<ChurnModelService>();

var app = builder.Build();

// Train on startup so the model file exists before any prediction requests
var churnService = app.Services.GetRequiredService<ChurnModelService>();
churnService.TrainModel();

// Load trained model for predictions
var mlContext = new Microsoft.ML.MLContext(seed: 42);
Microsoft.ML.ITransformer trainedModel;
using (var stream = File.OpenRead(churnService.ModelPath))
{
    trainedModel = mlContext.Model.Load(stream, out _);
}
var predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(trainedModel);
var predictionLock = new object();

app.MapGet("/", () => "Hello");

app.MapPost("/api/predict", (CustomerData customer) =>
{
    ChurnPrediction prediction;
    // PredictionEngine is not thread-safe; synchronize access
    lock (predictionLock)
    {
        prediction = predictionEngine.Predict(customer);
    }
    return Results.Ok(new
    {
        prediction.PredictedLabel,
        prediction.Probability,
        prediction.Score,
        WillChurn = prediction.PredictedLabel ? "Yes" : "No"
    });
});

app.MapGet("/api/model/metrics", () =>
{
    var metrics = churnService.Metrics;
    if (metrics is null)
        return Results.NotFound("Model has not been trained yet.");
    return Results.Ok(metrics);
});

app.Run();

