using Microsoft.ML;
using Microsoft.ML.Data;
using ChurnPredictor.Models;

namespace ChurnPredictor.Services;

public class ModelMetrics
{
    public double Accuracy { get; set; }
    public double Auc { get; set; }
    public double F1Score { get; set; }
    public double PositivePrecision { get; set; }
    public double PositiveRecall { get; set; }
}

public class ChurnModelService
{
    private readonly MLContext _mlContext;
    private readonly ILogger<ChurnModelService> _logger;
    private readonly string _modelPath;
    private readonly string _dataPath;

    public ModelMetrics? Metrics { get; private set; }
    public string ModelPath => _modelPath;

    public ChurnModelService(ILogger<ChurnModelService> logger, IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 42);
        _logger = logger;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "customers.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "churn_model.zip");
    }

    public void TrainModel()
    {
        _logger.LogInformation("Loading data from {Path}", _dataPath);

        // Load CSV rows with Churned as string
        var rawData = _mlContext.Data.LoadFromTextFile<CustomerCsvRow>(
            _dataPath, hasHeader: true, separatorChar: ',');

        // Convert to enumerable, map "Yes"/"No" to bool Label
        var rows = _mlContext.Data.CreateEnumerable<CustomerCsvRow>(rawData, reuseRowObject: false)
            .Select(r => new CustomerTrainingData
            {
                Age = r.Age,
                Income = r.Income,
                Region = r.Region,
                PurchaseHistory = r.PurchaseHistory,
                Label = string.Equals(r.Churned, "Yes", StringComparison.OrdinalIgnoreCase)
            })
            .ToList();

        var dataView = _mlContext.Data.LoadFromEnumerable(rows);
        var split = _mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region")
            .Append(_mlContext.Transforms.Concatenate("Features", "Age", "Income", "RegionEncoded", "PurchaseHistory"))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
                labelColumnName: "Label", featureColumnName: "Features"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        _logger.LogInformation("Evaluating model...");
        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

        Metrics = new ModelMetrics
        {
            Accuracy = metrics.Accuracy,
            Auc = metrics.AreaUnderRocCurve,
            F1Score = metrics.F1Score,
            PositivePrecision = metrics.PositivePrecision,
            PositiveRecall = metrics.PositiveRecall
        };

        _logger.LogInformation(
            "Model metrics — Accuracy: {Accuracy:F4}, AUC: {Auc:F4}, F1: {F1:F4}",
            Metrics.Accuracy, Metrics.Auc, Metrics.F1Score);

        _mlContext.Model.Save(model, dataView.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);
    }
}

